export function replayRtmr3(events: readonly RuntimeEvent[]) {
  if (
    !events.every(
      (entry) => isRecord(entry) && isText(entry.event) && isPayload(entry.event_payload),
    )
  )
    return { rtmr3: "", recorded: false };
  let rtmr: Uint8Array = new Uint8Array(48);
  let recorded = true;
  for (const entry of events) {
    const digest = runtimeEventDigest(entry.event, hexToBytes(entry.event_payload));
    recorded &&= entry.imr === 3 && entry.event_type === RUNTIME_EVENT_TYPE;
    recorded &&= bytesToHex(digest) === entry.digest;
    rtmr = sha384(concatBytes(rtmr, digest));
  }
  return { rtmr3: bytesToHex(rtmr), recorded };
}

export function eventPayload(events: readonly RuntimeEvent[], name: string): string | undefined {
  const matches = events.filter((entry) => entry.event === name);
  return matches.length === 1 ? matches[0]?.event_payload : undefined;
}

/** Only version 1 of dstack's mr_config_id binds the compose hash; any other value fails. */
export function mrConfigBindsCompose(mrConfigId: unknown, composeHash: string | undefined) {
  return isHex(composeHash, 32) && mrConfigId === `01${composeHash}${"00".repeat(15)}`;
}

export function notaryAddress(logKey: string, notaryKey: string): Uint8Array | undefined {
  try {
    const log = parseVerifierKey(logKey);
    const notary = parseVerifierKey(notaryKey);
    if (log.type !== ED25519 || notary.type !== COSIGNATURE_V1) return undefined;
    return signingAddress(log.publicKey, notary.publicKey);
  } catch {
    return undefined;
  }
}

export function checkpointNonce(checkpoint: string): string {
  return sha256Hex(utf8ToBytes(checkpoint));
}

export function checkpointSignedBy(checkpoint: string, logKey: string, notaryKey: string) {
  try {
    const keys = [parseVerifierKey(logKey), parseVerifierKey(notaryKey)];
    return openNote(utf8ToBytes(checkpoint), keys).verified.length === keys.length;
  } catch {
    return false;
  }
}

export type AttestationSubject = {
  readonly logKey: string;
  readonly notaryKey: string;
  readonly tlsKey: string;
  readonly callerNonce: string;
};

export function attestationRuntime(subject: AttestationSubject): Uint8Array | undefined {
  const address = notaryAddress(subject.logKey, subject.notaryKey);
  if (!address || !isHex(subject.tlsKey, 32) || !isHex(subject.callerNonce, 32)) return undefined;
  return itaAttestationRuntimeData(
    address,
    hexToBytes(subject.tlsKey),
    hexToBytes(subject.callerNonce),
  );
}

export type NotarySubject = {
  readonly logKey: string;
  readonly notaryKey: string;
  readonly previousCheckpoint: string | null;
  readonly callerNonce: string;
};

export function notaryRuntime(subject: NotarySubject): Uint8Array | undefined {
  if (!notaryAddress(subject.logKey, subject.notaryKey) || !isHex(subject.callerNonce, 32))
    return undefined;
  const previous =
    subject.previousCheckpoint === null ? undefined : utf8ToBytes(subject.previousCheckpoint);
  return itaNotaryRuntimeData(
    subject.logKey,
    subject.notaryKey,
    previous,
    hexToBytes(subject.callerNonce),
  );
}

export type SponsorSubject = {
  readonly accountId: string;
  readonly publicKeys: readonly string[];
  readonly callerNonce: string;
};

export function sponsorRuntime(subject: SponsorSubject): Uint8Array | undefined {
  if (!isHex(subject.callerNonce, 32)) return undefined;
  return itaSponsorRuntimeData(
    subject.accountId,
    subject.publicKeys,
    hexToBytes(subject.callerNonce),
  );
}

function reportDataBound(observed: ItaObservation, runtime: Buffer, tdx: Record<string, unknown>) {
  const { val, iat } = observed.verifierNonce;
  if (!isBase64(val) || !isBase64(iat)) return false;
  const bound = itaReportData(Buffer.from(val, "base64"), Buffer.from(iat, "base64"), runtime);
  return tdx.tdx_report_data === bytesToHex(bound);
}

function intelReadRuntimeData(runtime: Buffer, tdx: Record<string, unknown>) {
  try {
    return isDeepStrictEqual(tdx.attester_runtime_data, JSON.parse(runtime.toString("utf8")));
  } catch {
    return false;
  }
}

function attributesProduction(value: unknown) {
  if (!isHex(value, 8)) return false;
  return (
    tdAttributeFailures({ tdAttributes: hexToBytes(value), mrServiceTd: undefined }).length === 0
  );
}

function modulePatched(launch: unknown, current: unknown) {
  if (!isHex(launch, 16) || (current !== undefined && !isHex(current, 16))) return false;
  const teeTcbSvn2 = current === undefined ? undefined : hexToBytes(current);
  return tdxModuleFailures({ teeTcbSvn: hexToBytes(launch), teeTcbSvn2 }).length === 0;
}

function policyMatched(claims: JWTPayload, tdx: Record<string, unknown>, policyId: string) {
  const matched = [claims.policy_ids_matched, tdx.policy_ids_matched].flatMap((value) =>
    Array.isArray(value) ? value : [],
  );
  return matched.some((entry) => entry === policyId || (isRecord(entry) && entry.id === policyId));
}

function measurementsPinned(tdx: Record<string, unknown>, pinned: Measurements) {
  return (
    tdx.tdx_mrtd === pinned.mrtd &&
    tdx.tdx_rtmr0 === pinned.rtmr0 &&
    tdx.tdx_rtmr1 === pinned.rtmr1 &&
    tdx.tdx_rtmr2 === pinned.rtmr2
  );
}

export function assessItaToken(
  claims: JWTPayload,
  observed: ItaObservation,
  expected: ItaExpectations,
): Record<string, boolean> {
  const tdx = isRecord(claims.tdx) ? claims.tdx : {};
  const runtime = isBase64(observed.runtimeData)
    ? Buffer.from(observed.runtimeData, "base64")
    : Buffer.alloc(0);
  const replay = replayRtmr3(observed.eventLog);
  const advisories = tdx.attester_advisory_ids ?? [];
  const checks: Record<string, boolean> = {
    runtime_data_is_ours:
      expected.runtimeData !== undefined && runtime.equals(expected.runtimeData),
    intel_read_runtime_data: intelReadRuntimeData(runtime, tdx),
    report_data_bound: reportDataBound(observed, runtime, tdx),
    not_debuggable: tdx.tdx_is_debuggable === false,
    td_attributes_production: attributesProduction(tdx.tdx_td_attributes),
    tdx_module_patched: modulePatched(tdx.tdx_tee_tcb_svn, tdx.tdx_tee_tcb_svn2),
    tcb_accepted: expected.tcbStatuses.includes(String(tdx.attester_tcb_status)),
    no_advisories: Array.isArray(advisories) && advisories.length === 0,
    event_log_replays_rtmr3: replay.recorded && tdx.tdx_rtmr3 === replay.rtmr3,
    compose_hash_in_mr_config_id: mrConfigBindsCompose(
      tdx.tdx_mrconfigid,
      eventPayload(observed.eventLog, "compose-hash"),
    ),
  };
  if (expected.measurements !== undefined)
    checks.measurements_pinned = measurementsPinned(tdx, expected.measurements);
  if (claims.verifier_nonce !== undefined) {
    const nonce = isRecord(claims.verifier_nonce) ? claims.verifier_nonce : {};
    checks.verifier_nonce_from_intel =
      nonce.val === observed.verifierNonce.val && nonce.iat === observed.verifierNonce.iat;
  }
  if (expected.policyId !== undefined)
    checks.policy_matched = policyMatched(claims, tdx, expected.policyId);
  if (expected.appId !== undefined)
    checks.app_id_attested = eventPayload(observed.eventLog, "app-id") === expected.appId;
  if (expected.composeHash !== undefined)
    checks.compose_hash_attested =
      eventPayload(observed.eventLog, "compose-hash") === expected.composeHash;
  if (expected.composeHashAllowed !== undefined)
    checks.compose_hash_allowed_on_chain = expected.composeHashAllowed;
  return checks;
}

export type NotaryIta = {
  readonly token: string;
  readonly nonce: string;
  readonly checkpoint: string;
  readonly verifier_nonce: { readonly val: string; readonly iat: string };
  readonly runtime_data: string;
  readonly event_log: readonly RuntimeEvent[];
  readonly signing_key: Jwk;
};

export type TokenNotary = {
  readonly log_key: string;
  readonly notary_key: string;
  readonly birth: { readonly previous: { readonly note: string } | null };
  readonly ita: NotaryIta;
};

export type NotaryTokenOptions = Omit<TokenTrust, "keys"> & {
  readonly measurements: Measurements;
  readonly appId: string;
  readonly composeHash: string;
  readonly tcbStatuses?: readonly string[];
  readonly policyId?: string;
};

function wellFormed(notary: TokenNotary) {
  const { birth, ita } = notary;
  const previous: unknown = isRecord(birth) ? birth.previous : undefined;
  return (
    isText(notary.log_key) &&
    isText(notary.notary_key) &&
    (previous === null || (isRecord(previous) && isText(previous.note))) &&
    isRecord(ita) &&
    isText(ita.token) &&
    isHex(ita.nonce, 32) &&
    isText(ita.checkpoint) &&
    isRecord(ita.verifier_nonce) &&
    isText(ita.verifier_nonce.val) &&
    isText(ita.verifier_nonce.iat) &&
    isText(ita.runtime_data) &&
    Array.isArray(ita.event_log) &&
    isRecord(ita.signing_key)
  );
}

/** Accepts a token of any age: `claims.iat` says when Intel appraised the quote. */
export async function verifyNotaryToken(notary: TokenNotary, options: NotaryTokenOptions) {
  if (!wellFormed(notary)) fail("the stored token is malformed");
  const { ita } = notary;
  const { root, issuer, revocationList, now, tcbStatuses = ["UpToDate"], ...pins } = options;
  const trust = { root, issuer, keys: [ita.signing_key], revocationList, now };
  const claims = await verifyItaToken(ita.token, trust, { archived: true });
  const runtimeData = notaryRuntime({
    logKey: notary.log_key,
    notaryKey: notary.notary_key,
    previousCheckpoint: notary.birth.previous?.note ?? null,
    callerNonce: ita.nonce,
  });
  const observed = {
    verifierNonce: ita.verifier_nonce,
    runtimeData: ita.runtime_data,
    eventLog: ita.event_log,
  };
  const checks: Record<string, boolean> = {
    ...assessItaToken(claims, observed, { ...pins, tcbStatuses, runtimeData }),
    nonce_commits_to_checkpoint: checkpointNonce(ita.checkpoint) === ita.nonce,
    checkpoint_signed_by_notary: checkpointSignedBy(
      ita.checkpoint,
      notary.log_key,
      notary.notary_key,
    ),
  };
  return { claims, checks };
}
